import React, { useState } from 'react';
import {
    UserOutlined,
    NotificationOutlined,
    ContactsOutlined,
    SettingOutlined,
    MenuOutlined,
} from '@ant-design/icons';
import { Button, Menu } from 'antd';
import '../styles/Sidebar.css'; // Importar estilos del Sidebar

const Sidebar = () => {
    const [collapsed, setCollapsed] = useState(false);

    const toggleCollapsed = () => {
        setCollapsed(!collapsed);
    };

    const items = [
        { key: '1', icon: <UserOutlined />, label: 'Perfil' },
        { key: '2', icon: <NotificationOutlined />, label: 'Notificación' },
        { key: '3', icon: <ContactsOutlined />, label: 'Contacto' },
        { key: '4', icon: <SettingOutlined />, label: 'Configuraciones' },
    ];

    return (
        <div className={`sidebar ${collapsed ? 'collapsed' : ''}`}>
            <Button
                type="text"
                onClick={toggleCollapsed}
                className="menu-toggle"
            >
                <MenuOutlined />
            </Button>
            <Menu
                defaultSelectedKeys={['1']}
                mode="inline"
                theme="dark"
                inlineCollapsed={collapsed}
                items={items}
            />
        </div>
    );
};

export default Sidebar;
